Method.Implementation:
    Set tSC = $$$OK
    set usrNm = $get(%session.Data("UsNm"))
    set sql = "SELECT FileName, ImplDtTm, Instance, Revision, UserName, Description "
    _ " FROM IHC_ITF_SrcCtrlPkg.ITFCOMMONClasses "


   // Build WHERE clause based on filters
   set filterStr = $GET(pInfo.filters("FileName"))
    If (filterStr'="") {
        Set sql = sql _ " Where FileName [  '" _ filterStr _ "'"        
    }

    set filterStr2 = $GET(pInfo.filters("Instance"))
    If (filterStr2 '="") {
	    If (filterStr'="") {
		    Set sql = sql _ " AND Instance [  '" _ filterStr2 _ "'"
	    }
	    else
	    {
         Set sql = sql _ " Where Instance [  '" _ filterStr2 _ "'"        
	    }
    }

    set sql = sql _ " ORDER by ID desc" 

 	Set tRS = ##class(%Library.ResultSet).%New()
    If $IsObject(tRS) {
    	Set tSC = tRS.Prepare(sql)
    	Set pInfo.queryText = sql
    }

   Quit tRS

  try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
   set button = %page.%GetComponentById("changeFunc")
 	 if $ISOBJECT(button)
 	 {
	 	set button.caption = "Component Deployment"
 	 }
 } catch err
 {
 }
 return $$$OK
